const names = new Map([
  ["x", "X"],
  ["y", "Y"],
]);

const importedHelper = (name) => (names.has(name) ? names.get(name) : name);

function convertToolResult(name) {
  return importedHelper(name);
}

function convertMessages(name) {
  return importedHelper(name);
}

function scopeReplay(entries, marker) {
  function localHelper(value) {
    return `${marker}:${value}`;
  }
  for (const [filePath, enabled] of entries) {
    console.log(localHelper(`${filePath}:${enabled}`));
  }
}

export function run() {
  console.log(convertToolResult("x"));
  console.log(convertMessages("y"));
  scopeReplay(new Map([["a", true]]), 1);
  scopeReplay(new Map([["b", false]]), "two");
}
